mapper.update:
update dating_exception_followup set handler=#{handler},status=#{status},due_at=#{dueAt},
version=version+1,update_by=#{actor},update_time=current_timestamp(3)
where task_id=#{taskId} and version=#{version}

mapper.insert:
insert into dating_exception_followup_history(task_id,version,action,handler,status,due_at,note,create_by,create_time)
select task_id,version,#{action},handler,status,due_at,#{note},#{actor},current_timestamp(3)
from dating_exception_followup where task_id=#{taskId}
